const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2,minimumFractionDigits:0}).format(n);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={devices:{lumiere:true,ventilation:true,volets:false,eco:true},temp:22,water:68,beds:[47,62,38],cart:{},orders:[],posts:[],likes:[],bookings:[],harvest:[],checks:[]};let state;try{state={...defaults,...JSON.parse(localStorage.getItem('amap-vivante-v1')||'{}')}}catch{state=structuredClone(defaults)}function save(){try{localStorage.setItem('amap-vivante-v1',JSON.stringify(state))}catch{toast('Stockage indisponible : les changements restent dans cette session.')}}
const routes=[['accueil','⌂','Vue d’ensemble'],['habitat','▣','Mon container'],['jardin','♧','Mon jardin'],['communaute','◎','Vie commune'],['producteurs','♧','Marché local'],['antigaspi','▤','Labo anti-gaspi'],['projet','↗','Le projet']];const products=[{name:'Panier de saison',producer:'Les Jardins du Bocage',emoji:'🥬',price:15,unit:'panier',tag:'Panier du Domaine',color:'#e7ecd9',desc:'Un assortiment de légumes pour la semaine. Retrait au casier A12, jeudi de démonstration.'},{name:'Miel de fleurs',producer:'Rucher des Brandes',emoji:'🍯',price:9,unit:'500 g',tag:'Artisan local',color:'#f2e7cf',desc:'Miel toutes fleurs. Producteur et provenance fictifs, présentés pour illustrer le circuit court.'},{name:'Pain au levain',producer:'Fournil de la Place',emoji:'🍞',price:5,unit:'1 kg',tag:'Fait avec soin',color:'#eae1d1',desc:'Pain de campagne au levain. Précommande de démonstration, retrait le jeudi.'},{name:'Pommes du verger',producer:'Verger des Collines',emoji:'🍎',price:3.2,unit:'kg',tag:'De saison',color:'#ece9d6',desc:'Pommes du verger fictif des Collines. Quantité indicative : 1 kg par ajout.'},{name:'Bowl anti-gaspi',producer:'Le Labo du Lien',emoji:'🥗',price:11,unit:'repas',tag:'Anti-gaspi',color:'#e3e9d1',desc:'Recette illustrative à base de surplus de légumes. Allergènes à renseigner avant toute commercialisation réelle.'},{name:'Fromage de chèvre',producer:'Chèvrerie du Lay',emoji:'🧀',price:4.5,unit:'pièce',tag:'Circuit court',color:'#f1ebd9',desc:'Fromage artisanal fictif. Une fiche réelle devra préciser conservation, origine et allergènes.'}];
function scene(){return `<svg class="scene" viewBox="0 0 590 350" role="img" aria-label="Illustration d’une résidence en containers autour d’un potager partagé"><defs><pattern id="stripes" width="13" height="13" patternUnits="userSpaceOnUse"><path d="M0 0V13" stroke="#537261" stroke-width="1" opacity=".23"/></pattern><linearGradient id="ground" x2="1" y2="1"><stop stop-color="#d2dfb8"/><stop offset="1" stop-color="#e6ebd5"/></linearGradient></defs><ellipse cx="330" cy="294" rx="237" ry="36" fill="#bfcda6" opacity=".4"/><path d="M50 210 282 80 574 231 339 347Z" fill="url(#ground)"/><path d="M200 258 375 160 403 175 229 275Z" fill="#e7d6b4"/><path d="M125 173 249 104 374 171 250 242Z" fill="#bac9a3"/><g><path d="m130 138 128-70 153 80-126 72Z" fill="#c3c8b2"/><path d="m130 138 155 82v76l-155-82Z" fill="#426854"/><path d="m285 220 126-72v76l-126 72Z" fill="#74917a"/><path d="m130 138 155 82v76l-155-82Z" fill="url(#stripes)"/><path d="m146 160 50 27v44l-50-26Z" fill="#b7c7a3" stroke="#294f3d" stroke-width="4"/><path d="m205 192 52 28v44l-52-27Z" fill="#e9bd7a" stroke="#294f3d" stroke-width="4"/><path d="m308 218 43-25v55l-43 25Z" fill="#304e40"/><path d="m361 188 32-18v39l-32 19Z" fill="#c1d1b5"/><path d="m151 136 108-58 128 67-105 60Z" fill="#476b68"/><path d="m169 137 93-50 104 55-91 51Z" fill="#385f65" stroke="#9db7a0" stroke-width="1"/><path d="m199 121 101 55m-72-71 101 55m-72-71 101 55m-145 6 92-50m-61 67 92-50" stroke="#95b1aa" opacity=".7"/></g><g><path d="m350 98 82-46 109 56-83 47Z" fill="#d1ccb6"/><path d="m350 98 108 57v65l-108-58Z" fill="#d2b79a"/><path d="m458 155 83-47v65l-83 47Z" fill="#b19474"/><path d="m366 119 31 16v35l-31-17m44-12 30 16v35l-30-16" fill="#5a7661"/><path d="m474 155 44-25v35l-44 25Z" fill="#435f4f"/><path d="m354 92 78-44 111 58-86 47Z" fill="#acba98"/><path d="m371 89 60-33 94 49-67 37Z" fill="#798e67"/><path d="m402 77 88 46m-55-64 84 44" stroke="#adc49d" stroke-width="4"/></g><g fill="#8a6841" stroke="#ad8e61" stroke-width="4"><path d="m275 285 60-33 59 30-60 35Z"/><path d="m356 240 49-27 57 29-49 29Z"/></g><g fill="#6e9455"><ellipse cx="305" cy="279" rx="10" ry="6"/><ellipse cx="328" cy="267" rx="10" ry="6"/><ellipse cx="331" cy="293" rx="10" ry="6"/><ellipse cx="354" cy="279" rx="10" ry="6"/><ellipse cx="383" cy="239" rx="9" ry="6"/><ellipse cx="405" cy="227" rx="9" ry="6"/><ellipse cx="409" cy="251" rx="9" ry="6"/><ellipse cx="430" cy="239" rx="9" ry="6"/></g><g><path d="M82 227v-74m32 88v-63m424 69v-75" stroke="#938267" stroke-width="5"/><ellipse cx="82" cy="143" rx="29" ry="40" fill="#87a366"/><ellipse cx="107" cy="175" rx="21" ry="30" fill="#9cb579"/><ellipse cx="538" cy="174" rx="28" ry="43" fill="#7c9a60"/><ellipse cx="73" cy="134" rx="17" ry="25" fill="#99b277"/></g><path d="m202 285 30-17 29 15-29 17Z" fill="#a3926d"/><path d="M232 284v25" stroke="#7f785d" stroke-width="4"/><g><circle cx="276" cy="246" r="6" fill="#c99771"/><path d="m275 254-2 19m1-14-8 10m9-10 8 8m-10 5-5 12m6-12 6 10" stroke="#dc9767" stroke-width="5" stroke-linecap="round"/><circle cx="444" cy="248" r="6" fill="#b98362"/><path d="m443 256-2 18m1-14-9 7m10-7 8 6m-10 7-4 11m5-11 6 10" stroke="#526d51" stroke-width="5" stroke-linecap="round"/></g><rect x="397" y="34" width="141" height="24" rx="12" fill="#fff" opacity=".9"/><circle cx="410" cy="46" r="3" fill="#8da45d"/><text class="scenelabel" x="420" y="50">Un quotidien en commun</text></svg>`}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}function modal(html){$('#modalbody').innerHTML=html;$('#modal').showModal()}function heading(title,sub,action=''){return `<div class="pagehead"><div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}function stat(label,val,unit,note,icon){return `<div class="stat"><div class="statline"><span>${label}</span><span>${icon}</span></div><strong>${val} <small>${unit}</small></strong><p class="positive">${note}</p></div>`}function productsHTML(ids){return ids.map(i=>{const p=products[i];return `<article class="product"><button class="productart" style="background:${p.color};width:100%" aria-label="Voir ${p.name}" onclick="productDetail(${i})"><span class="mini">${p.tag}</span>${p.emoji}</button><div class="productbody"><h3>${p.name}</h3><p>${p.producer}</p><div class="price"><span>${money(p.price)} <small class="smallnote">/ ${p.unit}</small></span><button class="add" aria-label="Ajouter ${p.name} au panier" onclick="add(${i})">+</button></div></div></article>`}).join('')}
function home(){return heading('Bienvenue chez vous, Alex.','Votre lieu de vie, connecté à l’essentiel.',`<span class="datepill">☀ Journée de démonstration · 21 °C</span>`)+`<section class="hero"><div class="herotext"><div class="eyebrow">HABITER AUTREMENT, ENSEMBLE</div><h2>Un chez-soi.<br>Tout un écosystème.</h2><p>Pilotez votre habitat, cultivez votre jardin et partagez le quotidien de votre résidence.</p><button class="btn" onclick="openPresentation()">Découvrir le projet <span>↗</span></button></div>${scene()}</section><div class="stats">${stat('Autonomie solaire','78','%','Scénario énergétique fictif','☀')}${stat('Eau de pluie disponible',state.water,'%','Cuve · donnée simulée','◉')}${stat('Prochaine récolte','3','jours','Tomates · parcelle A03','♧')}${stat('Vie de la résidence','24','habitants','12 habitats · scénario fictif','◎')}</div><div class="twocol"><section class="panel"><div class="paneltop"><h2>Mon container</h2><a class="textlink" href="#habitat">Tout piloter ↗</a></div><div class="housecard"><div class="housevisual">${miniHouse()}</div><div><h3>Le Cocon · A03</h3><p>Un espace à vous, ouvert sur le vivant.<br><span class="mini">● ${state.devices.eco?'Mode éco actif':'Mode confort'}</span></p></div></div><div class="housemetrics"><div>Température simulée<b>${state.temp} °C</b></div><div>Énergie aujourd’hui<b>4,2 kWh</b></div><div>Humidité simulée<b>48 %</b></div></div></section><section class="panel"><div class="paneltop"><h2>À vivre ensemble</h2><a class="textlink" href="#communaute">L’agenda ↗</a></div>${event('JEU','29','Distribution des paniers','17 h – 19 h · Place commune','distribution')}${event('SAM','31','Atelier au potager','10 h · Jardin partagé','atelier')}</section></div><div class="sectiontitle"><h2>Du jardin à votre table.</h2><a class="textlink" href="#producteurs">Explorer le marché ↗</a></div><div class="productgrid">${productsHTML([0,1,2])}</div><p class="smallnote">Produits, producteurs et dates fictifs. Les commandes de cette maquette n’engagent aucun achat.</p>`}
function miniHouse(){return `<svg viewBox="0 0 120 80" width="100%" role="img" aria-label="Container végétalisé"><path d="m14 24 35-18 59 28-35 20Z" fill="#acbda0"/><path d="m14 24 59 30v23L14 47Z" fill="#52725b"/><path d="m73 54 35-20v23L73 77Z" fill="#759177"/><path d="m22 32 20 10v17L22 49Zm28 14 16 8v17l-16-8Z" fill="#d5c8a5"/><path d="m24 23 26-13 45 22-25 14Z" fill="#3d6266"/><path d="m40 17 44 23m-30-29 43 22" stroke="#8eafa4"/></svg>`}
function event(day,n,title,detail,id){return `<div class="event"><div class="day">${day}<b>${n}</b></div><div><h3>${title}</h3><p>${detail}</p></div><button class="textlink arrow" aria-label="Détails ${title}" onclick="eventDetail('${id}')">↗</button></div>`}
const devices={lumiere:['☼','Éclairage du séjour','Une lumière douce pour le quotidien.'],ventilation:['≋','Ventilation','Renouvellement de l’air intérieur.'],volets:['▤','Volets de la terrasse','Ouverture et fermeture simulées.'],eco:['♧','Mode éco','Un scénario de consommation réduite.']};function habitat(){return heading('Votre cocon, à portée de main.','Container A03 · Commandes de démonstration, sans liaison domotique.')+`<div class="twocol"><div class="panel" style="background:#e9eddb"><div class="paneltop"><h2>Le Cocon · A03</h2><span class="mini">Habitat fictif · 28 m²</span></div>${scene()}</div><div class="panel"><div class="eyebrow">CONFORT INTÉRIEUR</div><div class="bigreading"><span id="tempvalue">${state.temp}</span> <small>°C de consigne</small></div><label for="temperature">Régler la température souhaitée</label><input id="temperature" type="range" min="16" max="28" step="1" value="${state.temp}" oninput="setTemp(this.value)"><p class="sub">La consigne est mémorisée dans ce navigateur. Elle ne commande aucun chauffage.</p><div class="housemetrics" style="margin-top:25px"><div>Mesure simulée<b>21,5 °C</b></div><div>Humidité<b>48 %</b></div><div>Qualité de l’air<b>Bonne</b></div></div></div><div class="grid2">${Object.entries(devices).map(([k,d])=>`<article class="device ${state.devices[k]?'on':''}"><div class="devicehead"><span>${d[0]}</span><button class="switch" role="switch" aria-label="${d[1]}" aria-checked="${state.devices[k]}" onclick="toggleDevice('${k}')"></button></div><h3>${d[1]}</h3><p>${d[2]}</p><span class="mini">${state.devices[k]?'Activé':'Désactivé'} · simulation</span></article>`).join('')}</div><div class="panel"><h2>Les ressources du lieu</h2><label>Production solaire simulée · 78 % des besoins</label><div class="progress"><span style="width:78%"></span></div><label>Stock d’eau de pluie simulé · ${state.water} %</label><div class="progress"><span style="width:${state.water}%"></span></div><div class="notice">En version réelle : équipements compatibles, passerelle sécurisée, droits par logement et confirmation des actions sensibles seront nécessaires.</div><button class="btn light" onclick="maintenance()">Signaler un problème</button></div></div>`}
function toggleDevice(k){state.devices[k]=!state.devices[k];save();render();toast(devices[k][1]+' : '+(state.devices[k]?'activé':'désactivé')+' en simulation.')}function setTemp(v){state.temp=Number(v);$('#tempvalue').textContent=v;save()}function maintenance(){modal(`<h2>Une demande pour votre habitat</h2><p>Ticket local de démonstration. Aucun gestionnaire ne sera contacté.</p><form onsubmit="event.preventDefault();submitMaintenance(this)"><label for="issue">Décrivez le problème</label><textarea id="issue" name="issue" required maxlength="500" placeholder="Ex. : le volet de la terrasse reste bloqué"></textarea><button class="btn" style="margin-top:15px">Créer le ticket de démo</button></form>`)}function submitMaintenance(f){state.checks.push({text:f.issue.value,type:'maintenance'});save();$('#modal').close();toast('Ticket enregistré localement dans la démonstration.')}
const crops=[['Tomates anciennes','🍅','Parcelle A03 · votre jardin',3],['Salades & aromates','🥬','Parcelle commune B01',7],['Courges de saison','🎃','Parcelle commune B02',14]];function jardin(){return heading('Cultiver un peu. Partager beaucoup.','Vos parcelles, les ressources en eau et les récoltes du collectif.')+`<div class="stats">${stat('Votre parcelle','8','m²','Jardin A03 · fictif','♧')}${stat('Réserve d’eau',state.water,'%','Stock de démonstration','◉')}${stat('Récoltes enregistrées',state.harvest.length,'','Saisies locales dans la maquette','♧')}${stat('Compost partagé','62','%','Remplissage fictif','↻')}</div><div class="grid3">${crops.map((c,i)=>`<section class="panel"><div class="gardenbed"><span class="mini">Récolte estimée · J+${c[3]}</span><div class="plants">${c[1]} ${c[1]}</div></div><h3 style="margin-top:20px">${c[0]}</h3><p class="sub">${c[2]}</p><label>Humidité du sol · ${state.beds[i]} % (simulée)</label><div class="progress"><span style="width:${state.beds[i]}%"></span></div><button class="btn light" onclick="water(${i})">◉ Simuler un arrosage</button></section>`).join('')}</div><div class="twocol"><section class="panel"><h2>Votre carnet de récoltes</h2><form onsubmit="event.preventDefault();harvest(this)"><div class="formrow"><div><label for="crop">Récolte</label><select id="crop" name="crop"><option>Tomates</option><option>Salades</option><option>Courges</option><option>Aromates</option></select></div><div><label for="kg">Quantité (kg)</label><input id="kg" name="kg" type="number" required min="0.1" max="100" step="0.1" value="1"></div><button class="btn">Enregistrer</button></div></form>${state.harvest.length?state.harvest.map(h=>`<div class="event"><span>♧</span><div><h3>${esc(h.crop)}</h3><p>${esc(h.kg)} kg · récolte de démonstration</p></div></div>`).join(''):'<p class="smallnote">Enregistrez votre première récolte pour tester le carnet.</p>'}</section><section class="panel"><h2>Le prochain geste</h2><div class="featureline"><span>01</span><div><b>Observer avant d’arroser</b><p>Les valeurs de la maquette illustrent des capteurs. Le besoin réel dépend du sol, de la météo et des cultures.</p></div></div><div class="featureline"><span>02</span><div><b>Se retrouver au jardin</b><p>Atelier collectif samedi à 10 h. Découvrir le compost et organiser les prochaines plantations.</p><button class="textlink" onclick="eventDetail('atelier')">Réserver une place ↗</button></div></div></section></div>`}
function water(i){if(state.water<5){toast('Réserve simulée insuffisante pour cet arrosage.');return}state.beds[i]=Math.min(100,state.beds[i]+12);state.water-=5;save();render();toast('Arrosage simulé : humidité +12 points, réserve −5 points.')}function harvest(f){state.harvest.unshift({crop:f.crop.value,kg:Number(f.kg.value)});save();render();toast('Récolte ajoutée à votre carnet local.')}
const seedPosts=[{id:'p1',name:'Camille',initial:'CM',type:'Jardin partagé · exemple',text:'Les tomates commencent à rougir ! On se retrouve samedi pour la récolte et un atelier compost. Qui vient avec un panier ?'},{id:'p2',name:'Noé',initial:'ND',type:'Entraide · exemple',text:'J’ai une perceuse disponible pour le week-end. Vous pouvez la réserver dans les ressources partagées.'},{id:'p3',name:'Le collectif',initial:'CO',type:'Vie de la résidence · exemple',text:'Distribution des paniers jeudi de 17 h à 19 h. Pensez à apporter vos contenants pour limiter les emballages.'}];function communaute(){return heading('Un voisinage qui se rencontre.','Échanger, s’entraider et réserver les espaces communs — en démonstration.')+`<div class="twocol"><section class="panel"><div class="paneltop"><h2>Le fil du collectif</h2><span class="mini">Résidents fictifs</span></div><form onsubmit="event.preventDefault();post(this)"><label for="message">Partager avec la résidence</label><textarea id="message" name="message" required maxlength="500" placeholder="Une idée, un besoin, une récolte à partager…"></textarea><div style="display:flex;justify-content:space-between;align-items:center;margin-top:12px"><span class="smallnote">Visible uniquement dans ce navigateur.</span><button class="btn">Publier dans la démo</button></div></form>${[...state.posts,...seedPosts].map(p=>`<article class="post"><div class="posthead"><span class="avatar">${esc(p.initial)}</span><div>${esc(p.name)}<small>${esc(p.type)}</small></div></div><p>${esc(p.text)}</p><div class="postactions"><button aria-pressed="${state.likes.includes(p.id)}" onclick="like('${p.id}')">${state.likes.includes(p.id)?'♥ Merci !':'♡ J’aime'}</button><button onclick="reply('${p.id}')">↳ Répondre</button></div></article>`).join('')}</section><div><section class="panel"><h2>Le calendrier commun</h2>${event('JEU','29','Distribution des paniers','17 h – 19 h · Place commune','distribution')}${event('SAM','31','Atelier potager','10 h – 11 h · Jardin partagé','atelier')}${event('MAR','03','Conseil des habitants','18 h · Maison commune','conseil')}</section><section class="panel"><div class="paneltop"><h2>À partager</h2><span class="mini">Réservation fictive</span></div>${['Salle commune','Vélo cargo','Perceuse'].map((r,i)=>`<div class="event"><span style="font-size:26px">${['⌂','♧','⚒'][i]}</span><div><h3>${r}</h3><p>Créneaux de démonstration</p></div><button class="textlink" onclick="reserve('${r}')">Réserver ↗</button></div>`).join('')}</section><section class="panel"><h2>Mes inscriptions & réservations</h2>${state.bookings.length?state.bookings.map(b=>`<div class="event"><div><h3>${esc(b.name)}</h3><p>${esc(b.slot)} · démo</p></div><button class="textlink" onclick="cancelBooking('${b.id}')">Annuler</button></div>`).join(''):'<p class="smallnote">Aucune réservation dans cette démonstration.</p>'}</section></div></div>`}
function post(f){state.posts.unshift({id:'p'+Date.now(),name:'Alex',initial:'AL',type:'Votre message · local',text:f.message.value.trim()});save();render();toast('Message ajouté dans ce navigateur uniquement.')}function like(id){state.likes=state.likes.includes(id)?state.likes.filter(x=>x!==id):[...state.likes,id];save();render()}function reply(id){modal(`<h2>Répondre au collectif</h2><p>La réponse apparaîtra comme un message local de démonstration.</p><form onsubmit="event.preventDefault();post(this);document.getElementById('modal').close()"><label for="reply">Votre réponse</label><textarea id="reply" name="message" required maxlength="500"></textarea><button class="btn" style="margin-top:15px">Ajouter la réponse de démo</button></form>`)}
const events={atelier:['Atelier potager','Samedi 31 · 10 h – 11 h','Découvrir le compost, récolter les tomates et préparer les nouvelles plantations. Prévoir des gants.'],distribution:['Distribution des paniers','Jeudi 29 · 17 h – 19 h','Retrait des paniers au point commun et échange avec les producteurs. Créneau fictif.'],conseil:['Conseil des habitants','Mardi 3 · 18 h','Faire le point sur le jardin, les espaces partagés et les propositions du collectif.']};function eventDetail(id){const e=events[id];modal(`<div class="eyebrow">RENDEZ-VOUS DE DÉMONSTRATION</div><h2 style="margin-top:20px">${e[0]}</h2><p>${e[1]}</p><p>${e[2]}</p><button class="btn" onclick="book('${e[0]}','${e[1]}')">${state.bookings.some(b=>b.name===e[0])?'Déjà inscrit dans la démo':'M’inscrire dans la démo'}</button>`)}function reserve(name){modal(`<h2>Réserver : ${name}</h2><p>Ressource et disponibilités fictives. Cette action n’est partagée avec personne.</p><form onsubmit="event.preventDefault();book('${name}',this.slot.value)"><label for="slot">Choisir un créneau</label><select id="slot" name="slot"><option>Samedi · 10 h – 12 h</option><option>Samedi · 14 h – 16 h</option><option>Dimanche · 10 h – 12 h</option></select><button class="btn" style="margin-top:18px">Confirmer la réservation de démo</button></form>`)}function book(name,slot){if(state.bookings.some(b=>b.name===name&&b.slot===slot)){toast('Cette inscription est déjà enregistrée.');return}state.bookings.push({name,slot,id:String(Date.now())});save();$('#modal').close();render();toast('Inscription de démo enregistrée localement.')}function cancelBooking(id){state.bookings=state.bookings.filter(b=>b.id!==id);save();render();toast('Réservation de démo annulée.')}
function productDetail(i){let p=products[i];modal(`<div style="font-size:70px;background:${p.color};text-align:center;border-radius:12px;padding:20px">${p.emoji}</div><h2 style="margin-top:20px">${p.name}</h2><p>${p.producer} · producteur fictif</p><p>${p.desc}</p><div class="total"><span>${money(p.price)} / ${p.unit}</span><button class="btn" onclick="add(${i})">Ajouter au panier</button></div><p class="smallnote">Aucune commande réelle. Aucune certification biologique vérifiée dans cette maquette.</p>`)}function add(i){state.cart[i]=(state.cart[i]||0)+1;save();toast(products[i].name+' ajouté au panier de démo.');if(location.hash==='#producteurs')render()}function market(){return heading('Le local, au fil des saisons.','La vie du Domaine : paniers, producteurs, retrait et repas anti-gaspi.',`<button class="btn" onclick="cartModal()">Mon panier · ${Object.values(state.cart).reduce((a,b)=>a+b,0)}</button>`)+`<div class="panel" style="background:#e9eddb"><div class="paneltop" style="margin-bottom:0"><div><div class="eyebrow">CIRCUITS COURTS · DÉMONSTRATION</div><h2 style="font-size:25px;margin:14px 0 10px">Du producteur au lieu de vie.</h2><p class="sub">Retrait fictif le jeudi · casiers réfrigérés au cœur de la résidence.<br>Les prix et les producteurs illustrent le parcours, sans vente réelle.</p></div><span style="font-size:60px">🧺</span></div></div><label for="filter">Explorer les produits</label><select id="filter" style="max-width:300px;margin-bottom:20px" onchange="filterProducts(this.value)"><option value="all">Tous les produits</option><option value="amap">Paniers & produits fermiers</option><option value="repas">Repas anti-gaspi</option></select><div id="products" class="productgrid">${productsHTML([0,1,2,3,4,5])}</div><section class="panel" style="margin-top:25px"><h2>Mes commandes de démonstration</h2>${state.orders.length?state.orders.map(o=>`<div class="event"><span>🧺</span><div><h3>${esc(o.id)} · ${money(o.total)}</h3><p>Retrait fictif : ${esc(o.slot)} · ${o.count} article(s)</p></div><span class="mini">Simulée</span></div>`).join(''):'<p class="smallnote">Validez un panier fictif pour tester le suivi des commandes et le retrait en casier.</p>'}</section>`}function filterProducts(v){$('#products').innerHTML=productsHTML(v==='repas'?[4]:v==='amap'?[0,1,2,3,5]:[0,1,2,3,4,5])}function total(){return Object.entries(state.cart).reduce((a,[i,q])=>a+products[i].price*q,0)}function cartModal(){modal(`<h2>Votre panier local</h2><p class="smallnote">Simulation uniquement · aucun paiement ni livraison réelle.</p>${Object.keys(state.cart).length?Object.entries(state.cart).map(([i,q])=>`<div class="cartline"><span style="font-size:30px">${products[i].emoji}</span><div>${products[i].name}<br><small>${money(products[i].price)} / ${products[i].unit}</small></div><button aria-label="Retirer une unité de ${products[i].name}" onclick="quantity(${i},-1)">−</button><span>${q}</span><button aria-label="Ajouter une unité de ${products[i].name}" onclick="quantity(${i},1)">+</button></div>`).join('')+`<div class="total"><span>Total indicatif</span><b>${money(total())}</b></div><label for="pickup">Créneau de retrait fictif</label><select id="pickup"><option>Jeudi · 17 h – 18 h</option><option>Jeudi · 18 h – 19 h</option></select><button class="btn" style="margin-top:20px;width:100%" onclick="checkout()">Valider la commande de démonstration</button>`:'<div class="empty">Votre panier attend ses premiers produits.<br>Ajoutez un panier ou un repas pour essayer.</div>'}`)}function quantity(i,d){state.cart[i]+=d;if(state.cart[i]<=0)delete state.cart[i];save();$('#modal').close();cartModal();render()}function checkout(){const o={id:'DÉMO-'+String(Date.now()).slice(-5),total:total(),count:Object.values(state.cart).reduce((a,b)=>a+b,0),slot:$('#pickup').value};state.orders.unshift(o);state.cart={};save();$('#modal').close();render();modal(`<div style="font-size:55px">✓</div><h2>Commande simulée enregistrée.</h2><p>${o.id} · ${money(o.total)}</p><p>Retrait fictif ${o.slot}, casier A12.<br>Code de démonstration : <b>0427</b>.</p><div class="notice">Ce code n’ouvre aucun casier. Aucun producteur n’a reçu cette commande et aucun paiement n’a été effectué.</div><button class="btn" onclick="document.getElementById('modal').close()">Revenir au marché</button>`)}
function antigaspi(){return heading('Transformer les surplus en ressources.','Un laboratoire en container, relié aux producteurs et aux habitants.')+`<div class="hero"><div class="herotext"><div class="eyebrow">DU DOCUMENT AU PARCOURS INTERACTIF</div><h2>Moins de pertes.<br>Plus de liens.</h2><p>Collecter les surplus, préparer des repas et organiser leur retrait en casiers réfrigérés.</p><button class="btn" onclick="batch()">＋ Créer un lot de démonstration</button></div>${scene()}</div><div class="stats">${stat('Container 20 pieds','54 000','€ HT','Besoin initial · document fourni','▣')}${stat('Container 40 pieds','61 000','€ HT','Besoin initial · document fourni','▣')}${stat('Prix du repas','11','€','Hypothèse du prévisionnel','♧')}${stat('Jours d’activité','210','/ an','Hypothèse du prévisionnel','↻')}</div><div class="twocol"><section class="panel"><h2>Tester le modèle économique</h2><p class="smallnote">Simulation basée sur le document « Container de transformation anti gaspi prévisionnel 2027 ». Le résultat affiché est un solde simplifié, pas un bénéfice net validé.</p><label for="meals">Repas vendus par jour : <b id="mealcount">65</b></label><input id="meals" type="range" min="10" max="100" value="65" oninput="financeCalc()"><div class="formrow"><div><label for="price">Prix du repas (€)</label><input id="price" type="number" min="1" max="100" step="0.5" value="11" oninput="financeCalc()"></div><div><label for="days">Jours d’activité</label><input id="days" type="number" min="1" max="366" value="210" oninput="financeCalc()"></div></div><div class="notice">Hypothèses conservées : 6 000 € d’adhésions et commissions, coût matière de 20 % des ventes de repas, autres charges de 65 600 €. Financement, fiscalité, amortissements et exhaustivité des charges restent à vérifier.</div></section><section class="finance"><div class="eyebrow" style="color:#c4d5ad">PROJECTION ANNUELLE SIMPLIFIÉE</div><div class="bigreading" id="balance">60 520 €</div><p class="sub">Solde produits − charges listées</p><div class="budgetrow"><span>Ventes de repas</span><b id="sales">150 150 €</b></div><div class="budgetrow"><span>Adhésions + commissions</span><b>6 000 €</b></div><div class="budgetrow"><span>Produits totaux</span><b id="revenue">156 150 €</b></div><div class="budgetrow"><span>Charges listées</span><b id="cost">95 630 €</b></div><p class="smallnote">Repère calculé sous ces hypothèses : environ <span id="breakeven">33</span> repas par jour pour couvrir les charges listées. Aucune promesse de rentabilité.</p></section></div><div class="grid3">${['Collecter & tracer','Transformer & conserver','Distribuer & valoriser'].map((x,i)=>`<section class="panel"><span class="eyebrow">0${i+1}</span><h3 style="margin-top:16px">${x}</h3><p class="sub">${['Enregistrer le producteur, les quantités reçues et la date de collecte.','Suivre un lot, sa recette et les informations de conservation et d’allergènes.','Associer un lot à un casier, un créneau et une quantité disponible.'][i]}</p></section>`).join('')}</div><section class="panel"><h2>Lots de démonstration</h2>${state.checks.filter(c=>c.type==='batch').length?state.checks.filter(c=>c.type==='batch').map(c=>`<div class="event"><div><h3>${esc(c.text)}</h3><p>${esc(c.qty)} portions · préparation fictive · conservation non validée</p></div><span class="mini">Brouillon</span></div>`).join(''):'<p class="smallnote">Aucun lot créé. Utilisez le bouton au-dessus pour simuler une production.</p>'}<p class="smallnote">Cette maquette ne constitue pas un registre sanitaire. Les conditions d’implantation et de mise en service doivent être validées avec les interlocuteurs compétents.</p></section>`}function financeCalc(){let meals=Number($('#meals').value),p=Number($('#price').value),d=Number($('#days').value);$('#mealcount').textContent=meals;if(p<=0||d<=0){return}let sales=meals*p*d,cost=65600+.2*sales;$('#sales').textContent=money(sales);$('#revenue').textContent=money(sales+6000);$('#cost').textContent=money(cost);$('#balance').textContent=money(sales+6000-cost);$('#breakeven').textContent=Math.ceil(59600/(p*d*.8))}function batch(){modal(`<h2>Créer un lot fictif</h2><p>Testez le suivi des préparations, sans production réelle.</p><form onsubmit="event.preventDefault();createBatch(this)"><label for="recipe">Nom de la recette</label><input id="recipe" name="recipe" required maxlength="80" placeholder="Ex. : soupe de légumes du jardin"><label for="portions">Nombre de portions</label><input id="portions" name="portions" type="number" required min="1" max="500" value="20"><button class="btn" style="margin-top:20px">Enregistrer le brouillon de démo</button></form>`)}function createBatch(f){state.checks.push({type:'batch',text:f.recipe.value,qty:Number(f.portions.value)});save();$('#modal').close();render();toast('Lot fictif ajouté au suivi du laboratoire.')}
function projet(){return heading('Une résidence. Un écosystème vivant.','Présentation du concept et périmètre de cette maquette.',`<button class="btn" onclick="openPresentation()">▷ Lancer la présentation</button>`)+`<div class="hero"><div class="herotext"><div class="eyebrow">Domaine · V2 FUSION</div><h2>Relier l’habitat,<br>la terre et les gens.</h2><p>Une application commune pour vivre chez soi et agir à l’échelle du collectif.</p><div class="tagrow"><span>Habitat connecté</span><span>Jardins</span><span>Entraide</span><span>Circuits courts</span></div></div>${scene()}</div><div class="grid3" style="margin-top:24px">${[['01','Pour les habitants','Piloter son container, suivre son jardin, réserver les espaces et commander un panier.'],['02','Pour le collectif','Animer les rendez-vous, coordonner les ressources et organiser la vie de la résidence.'],['03','Pour les producteurs','Présenter ses produits, préparer les retraits et valoriser les surplus au laboratoire.']].map(x=>`<section class="panel"><span class="eyebrow">${x[0]}</span><h3 style="margin-top:17px">${x[1]}</h3><p class="sub">${x[2]}</p></section>`).join('')}</div><div class="twocol"><section class="panel"><h2>De l’idée à la résidence</h2><div class="timeline"><div class="step"><h3>1 · Présenter et tester</h3><p>Cette version : parcours interactifs et exemples fictifs pour recueillir les retours.</p></div><div class="step"><h3>2 · Cadrer un lieu pilote</h3><p>Identifier le terrain, les besoins des habitants, les producteurs et le budget réel. Valider les conditions d’implantation.</p></div><div class="step"><h3>3 · Connecter les services</h3><p>Comptes individuels, stockage partagé, réservation multiutilisateur et gestion des commandes.</p></div><div class="step"><h3>4 · Relier les équipements</h3><p>Installer et tester les passerelles, les capteurs et les permissions de commande avec des professionnels.</p></div></div></section><section class="panel"><h2>Ce que vous pouvez essayer ici</h2><div class="featureline"><span>✓</span><div><b>Des interactions fonctionnelles</b><p>Consigne, interrupteurs, arrosage, carnet de récoltes, messages, réservations, panier et simulation financière.</p></div></div><div class="featureline"><span>◉</span><div><b>Des données locales de démonstration</b><p>Les changements sont conservés sur cet appareil dans ce navigateur. Il n’y a ni compte, ni synchronisation entre habitants.</p></div></div><div class="featureline"><span>↗</span><div><b>La vie du Domaine</b><p>Le marché et les producteurs prolongent la maquette existante. Le container de transformation reprend les hypothèses du document fourni.</p><a class="textlink" href="https://amapyon-v2-fusion-demo.lovable.app/" target="_blank" rel="noopener">Voir la référence d’origine ↗</a></div></div><button class="btn light" style="margin-top:20px" onclick="exportDemo()">Exporter mes essais en JSON</button><button class="textlink" style="display:block;margin-top:14px" onclick="resetModal()">Réinitialiser les données de démonstration</button></section></div>`}
function notifications(){modal(`<h2>Le fil de votre journée</h2><p>Exemples de notifications de la résidence.</p><div class="featureline"><span>♧</span><div><b>Votre jardin</b><p>Récolte des tomates estimée dans trois jours.</p></div></div><div class="featureline"><span>🧺</span><div><b>Vos paniers</b><p>Distribution fictive jeudi, de 17 h à 19 h.</p></div></div><div class="featureline"><span>◎</span><div><b>Le collectif</b><p>Un atelier potager est proposé samedi.</p></div></div>`)}function exportDemo(){const b=new Blob([JSON.stringify({version:1,demonstration:true,data:state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='amapyon-mes-essais.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Export de vos essais préparé.')}function resetModal(){modal(`<h2>Recommencer la démonstration ?</h2><p>Cela efface uniquement les essais Domaine de ce navigateur : messages, réservations, panier et réglages.</p><button class="btn" onclick="resetDemo()">Réinitialiser mes essais</button>`)}function resetDemo(){state=structuredClone(defaults);save();$('#modal').close();render();toast('La démonstration a retrouvé ses données initiales.')}
const slides=[{k:'01 · LA VISION',title:'Un chez-soi.<br>Tout un écosystème.',text:'Domaine relie habitat connecté, jardin, vie commune et producteurs locaux dans un seul espace.',cards:[['Habiter','Un container confortable et des ressources suivies.'],['Cultiver','Un jardin personnel et des parcelles partagées.'],['Partager','Des voisins, des services et une alimentation locale.']]},{k:'02 · UNE JOURNÉE DANS LA RÉSIDENCE',title:'Du matin au panier du soir.',text:'Un parcours concret pour comprendre la valeur du projet.',cards:[['08 h · Mon habitat','Consulter l’énergie et ajuster la consigne de confort.'],['12 h · Mon jardin','Observer les cultures et noter la récolte du jour.'],['18 h · Le collectif','Retirer son panier et se retrouver à la maison commune.']]},{k:'03 · L’APPLICATION',title:'Tout ce qui fait<br>la vie du lieu.',text:'Six espaces complémentaires : vue d’ensemble, container, jardin, vie commune, marché local et laboratoire anti-gaspi.',cards:[['Résident','Ses réglages, son jardin, ses achats et ses réservations.'],['Collectif','Les espaces, les rendez-vous et les ressources à partager.'],['Producteur','Les paniers, les distributions et les surplus à valoriser.']]},{k:'04 · LA BOUCLE LOCALE',title:'Ce qui reste<br>peut devenir une ressource.',text:'Les surplus des producteurs alimentent un laboratoire de transformation. Les repas préparés rejoignent des casiers de retrait.',cards:[['Collecte','Quantités reçues et lots à tracer.'],['Transformation','Recettes, conservation et allergènes à documenter.'],['Distribution','Repas et paniers accessibles sur un créneau choisi.']]},{k:'05 · LE MODÈLE À TESTER',title:'Des hypothèses visibles.<br>Un modèle à confronter au réel.',text:'Le document fourni estime le besoin initial à 54 000 € HT pour le scénario 20 pieds et 61 000 € HT pour le 40 pieds, casiers et trésorerie inclus.',cards:[['65 repas / jour','Hypothèse à 11 € sur 210 jours d’activité.'],['156 150 € / an','Produits annuels du prévisionnel fourni.'],['60 520 € / an','Solde simplifié avant vérification des coûts, du financement et de la fiscalité.']]},{k:'06 · LA SUITE',title:'Commencer par un lieu.<br>Grandir avec ses habitants.',text:'Cette démonstration sert à discuter le projet. Les prochaines décisions portent sur le terrain, les usages, les partenaires et un budget complet.',cards:[['Tester','Faire essayer les parcours à des futurs usagers.'],['Cadrer','Valider le lieu, le montage et les conditions de mise en service.'],['Construire','Connecter les comptes et les équipements après validation.']]}];let slideIndex=0;function openPresentation(){slideIndex=0;renderSlide();$('#deck').showModal()}function slideChange(d){slideIndex=Math.max(0,Math.min(slides.length-1,slideIndex+d));renderSlide()}function renderSlide(){const s=slides[slideIndex];$('#slide').innerHTML=`<div class="over"><div class="eyebrow">${s.k}</div><h2>${s.title}</h2><p>${s.text}</p><div class="grid3">${s.cards.map(c=>`<div class="panel"><h3>${c[0]}</h3><p class="sub" style="font-size:12px">${c[1]}</p></div>`).join('')}</div><span class="smallnote">Concept de démonstration · données fictives · aucune installation réelle connectée</span>${slideIndex===5?'<button class="btn" style="margin-top:15px" onclick="document.getElementById(\'deck\').close();location.hash=\'#habitat\'">Essayer l’application ↗</button>':''}</div>`;$('#slidecount').textContent=`${slideIndex+1} / ${slides.length}`;let b=$('#deck').querySelectorAll('.deckbar button');b[0].disabled=slideIndex===0;b[1].disabled=slideIndex===slides.length-1}document.addEventListener('keydown',e=>{if($('#deck').open){if(e.key==='ArrowRight')slideChange(1);if(e.key==='ArrowLeft')slideChange(-1)}});
const views={accueil:home,habitat,jardin,communaute,producteurs:market,antigaspi,projet};function render(){let route=location.hash.slice(1)||'accueil';if(!views[route])route='accueil';$('#nav').innerHTML=routes.map(r=>`<a href="#${r[0]}" class="${r[0]===route?'active':''}" ${r[0]===route?'aria-current="page"':''}><span class="navicon">${r[1]}</span>${r[2]}${r[0]==='communaute'?'<span class="badge">3</span>':''}</a>`).join('');$('#crumb').textContent=routes.find(r=>r[0]===route)[2];$('#main').innerHTML=`<div class="view">${views[route]()}</div>`;document.title=routes.find(r=>r[0]===route)[2]+' · Domaine';}window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});render();
